public class InnerActionConnectorAuthenticationMetadataFactory(Action<Humidifier.QuickSight.ActionConnectorTypes.AuthenticationMetadata> factoryAction = null) : SubResourceFactory<Humidifier.QuickSight.ActionConnectorTypes.AuthenticationMetadata>
{

    internal InnerActionConnectorBasicAuthConnectionMetadataFactory BasicAuthConnectionMetadataFactory { get; set; }

    internal InnerActionConnectorIAMConnectionMetadataFactory IamConnectionMetadataFactory { get; set; }

    internal InnerActionConnectorAuthorizationCodeGrantMetadataFactory AuthorizationCodeGrantMetadataFactory { get; set; }

    internal InnerActionConnectorClientCredentialsGrantMetadataFactory ClientCredentialsGrantMetadataFactory { get; set; }

    internal InnerActionConnectorNoneConnectionMetadataFactory NoneConnectionMetadataFactory { get; set; }

    internal InnerActionConnectorAPIKeyConnectionMetadataFactory ApiKeyConnectionMetadataFactory { get; set; }

    protected override Humidifier.QuickSight.ActionConnectorTypes.AuthenticationMetadata Create()
    {
        var authenticationMetadataResult = CreateAuthenticationMetadata();
        factoryAction?.Invoke(authenticationMetadataResult);

        return authenticationMetadataResult;
    }

    private Humidifier.QuickSight.ActionConnectorTypes.AuthenticationMetadata CreateAuthenticationMetadata()
    {
        var authenticationMetadataResult = new Humidifier.QuickSight.ActionConnectorTypes.AuthenticationMetadata();

        return authenticationMetadataResult;
    }
    public override void CreateChildren(Humidifier.QuickSight.ActionConnectorTypes.AuthenticationMetadata result)
    {
        base.CreateChildren(result);

        result.BasicAuthConnectionMetadata ??= BasicAuthConnectionMetadataFactory?.Build();
        result.IamConnectionMetadata ??= IamConnectionMetadataFactory?.Build();
        result.AuthorizationCodeGrantMetadata ??= AuthorizationCodeGrantMetadataFactory?.Build();
        result.ClientCredentialsGrantMetadata ??= ClientCredentialsGrantMetadataFactory?.Build();
        result.NoneConnectionMetadata ??= NoneConnectionMetadataFactory?.Build();
        result.ApiKeyConnectionMetadata ??= ApiKeyConnectionMetadataFactory?.Build();
    }

} // End Of Class

